css:
.sl-hero-universe {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-universe .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-universe .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-universe .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-universe .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-universe .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-universe .sl-bg-primary {
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-universe .sl-tint-primary {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, var(--smartlearn-bg));
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-universe .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-universe .sl-btn-primary:hover,
.sl-hero-universe .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-universe .sl-blob {
  position: absolute;
  width: 380px;
  height: 380px;
  pointer-events: none;
}
.sl-hero-universe .blob-1 {
  top: -80px;
  inset-inline-start: -80px;
  fill: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-hero-universe .blob-2 {
  bottom: -80px;
  inset-inline-end: -60px;
  fill: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
}
.sl-hero-universe .sl-universe-title {
  letter-spacing: -0.03em;
}
.sl-hero-universe .sl-search-form {
  background-color: var(--smartlearn-input-bg);
  border-color: var(--smartlearn-input-border, var(--smartlearn-card-border));
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.sl-hero-universe .sl-search-input {
  color: var(--smartlearn-text);
}
.sl-hero-universe .sl-search-input::placeholder {
  color: var(--smartlearn-text-muted);
}
.sl-hero-universe .sl-search-input:focus-visible {
  outline: 2px solid var(--smartlearn-primary);
  outline-offset: 2px;
}
.sl-hero-universe .sl-avatar-chip,
.sl-hero-universe .sl-avatar-count {
  width: 40px;
  height: 40px;
  border: 2px solid var(--smartlearn-bg);
}
.sl-hero-universe .sl-avatar-chip {
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-universe .sl-avatar-chip + .sl-avatar-chip,
.sl-hero-universe .sl-avatar-count {
  margin-inline-start: -10px;
}
.sl-hero-universe .sl-avatar-count {
  background-color: var(--smartlearn-card-bg);
  color: var(--smartlearn-text);
  border-color: var(--smartlearn-card-border);
}
.sl-hero-universe .sl-universe-stage {
  min-height: 480px;
  perspective: 1000px;
}
.sl-hero-universe .sl-card-thumb { height: 120px; }
.sl-hero-universe .sl-card-thumb-lg { height: 140px; }
.sl-hero-universe .sl-card-thumb-sm { height: 100px; }
.sl-hero-universe .sl-float-card {
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform-style: preserve-3d;
}
.sl-hero-universe .card-1 {
  width: 240px;
  top: 4%;
  inset-inline-start: 6%;
  z-index: 1;
}
.sl-hero-universe .card-2 {
  width: 280px;
  top: 24%;
  inset-inline-end: 4%;
  z-index: 3;
}
.sl-hero-universe .card-3 {
  width: 220px;
  bottom: 4%;
  inset-inline-start: 26%;
  z-index: 2;
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-universe .sl-search-form:focus-within {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
  }
  .sl-hero-universe .sl-float-card:hover {
    transform: translateZ(24px) scale(1.04);
    z-index: 10;
  }
  .sl-hero-universe .card-1 { animation: sl-hero-universe-float 8s ease-in-out infinite; }
  .sl-hero-universe .card-2 { animation: sl-hero-universe-float 10s ease-in-out infinite reverse; }
  .sl-hero-universe .card-3 { animation: sl-hero-universe-float 9s ease-in-out infinite 1.5s; }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-universe .card-1,
  .sl-hero-universe .card-2,
  .sl-hero-universe .card-3 {
    animation: none;
    transition: none;
  }
}
@keyframes sl-hero-universe-float {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-14px) rotate(1.5deg); }
}
